// db.js - an in-memory Postgres, ready to use. You do NOT edit this file.
import { newDb } from 'pg-mem'

const SCHEMA = `
  CREATE TABLE artists (
    id    SERIAL PRIMARY KEY,
    name  TEXT NOT NULL,
    genre TEXT NOT NULL
  );
  CREATE TABLE plays (
    id            SERIAL PRIMARY KEY,
    artist_id     INTEGER NOT NULL REFERENCES artists(id),
    listener      TEXT NOT NULL,
    duration_secs INTEGER NOT NULL,
    played_at     DATE NOT NULL
  );
`

const ARTISTS = [
  ['Taylor Swift', 'pop'],
  ['Ed Sheeran', 'pop'],
  ['The Weeknd', 'r&b'],
  ['SZA', 'r&b'],
  ['Metallica', 'rock'],
  ['AC/DC', 'rock'],
  ['Daft Punk', 'electronic'],
  ['Skrillex', 'electronic']
]

const LISTENERS = ['Alex', 'Jordan', 'Taylor', 'Morgan', 'Sam', 'Riley']

function makeRows(n) {
  let x = 20260912
  const next = () => (x = (x * 1103515245 + 12345) & 0x7fffffff)
  const rows = []
  for (let i = 0; i < n; i++) {
    const bits = () => (next() >>> 8) & 0xffff
    const artist_id = 1 + (bits() % ARTISTS.length)
    const listener = LISTENERS[bits() % LISTENERS.length]
    const duration_secs = 60 + (bits() % 240) // 60s to 299s
    const month = 1 + (bits() % 6)
    const day = 1 + (bits() % 28)
    const played_at = `2026-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`
    rows.push({ artist_id, listener, duration_secs, played_at })
  }
  return rows
}

const db = newDb()
db.public.none(SCHEMA)
for (const [name, genre] of ARTISTS) {
  db.public.none(`INSERT INTO artists (name, genre) VALUES ('${name.replace(/'/g, "''")}', '${genre}')`)
}
for (const r of makeRows(200)) {
  db.public.none(
    `INSERT INTO plays (artist_id, listener, duration_secs, played_at) VALUES (${r.artist_id}, '${r.listener}', ${r.duration_secs}, '${r.played_at}')`
  )
}
const { Pool } = db.adapters.createPg()
export const pool = new Pool()
